INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_aj-5-present-simple-3rd_0','Doplň: She ... tennis. (play)',ARRAY['playing','played','play','plays']::TEXT[],3,'He/she/it přidává -s.',1,ARRAY[]::TEXT[],NULL,0,'c_aj-5-present-simple-3rd',NULL,NOW()),
('q_aj-5-present-simple-3rd_1','Doplň: He ... milk. (drink)',ARRAY['drink','drinks','drank','drinking']::TEXT[],1,'He drinks.',1,ARRAY[]::TEXT[],NULL,1,'c_aj-5-present-simple-3rd',NULL,NOW()),
('q_aj-5-present-simple-3rd_2','Doplň: It ... at night. (sleep)',ARRAY['sleep','slept','sleeping','sleeps']::TEXT[],3,'It sleeps.',1,ARRAY[]::TEXT[],NULL,2,'c_aj-5-present-simple-3rd',NULL,NOW()),
('q_aj-5-present-simple-3rd_3','Doplň: My dad ... a car. (drive)',ARRAY['drive','drove','drives','driving']::TEXT[],2,'Dad = he → drives.',2,ARRAY[]::TEXT[],NULL,3,'c_aj-5-present-simple-3rd',NULL,NOW()),
('q_aj-5-present-simple-3rd_4','Doplň: She ... TV every evening. (watch)',ARRAY['watchs','watch','watching','watches']::TEXT[],3,'Po -ch přidáváme -es.',2,ARRAY[]::TEXT[],NULL,4,'c_aj-5-present-simple-3rd',NULL,NOW()),
('q_aj-5-present-simple-3rd_5','Doplň: He ... his teeth. (brush)',ARRAY['brush','brushing','brushes','brushs']::TEXT[],2,'Po -sh přidáváme -es.',2,ARRAY[]::TEXT[],NULL,5,'c_aj-5-present-simple-3rd',NULL,NOW()),
('q_aj-5-present-simple-3rd_6','Doplň: She ... to school by bus. (go)',ARRAY['go','goes','gos','going']::TEXT[],1,'Go → goes.',3,ARRAY[]::TEXT[],NULL,6,'c_aj-5-present-simple-3rd',NULL,NOW()),
('q_aj-5-present-simple-3rd_7','Doplň: He ... English very well. (study)',ARRAY['studies','studys','studyes','study']::TEXT[],0,'Y po souhlásce → -ies.',3,ARRAY[]::TEXT[],NULL,7,'c_aj-5-present-simple-3rd',NULL,NOW()),
('q_aj-5-present-simple-3rd_8','Zápor od She plays chess je…',ARRAY['She don''t play chess.','She doesn''t play chess.','She doesn''t plays chess.','She not play chess.']::TEXT[],1,'Doesn''t + základní tvar.',3,ARRAY[]::TEXT[],NULL,8,'c_aj-5-present-simple-3rd',NULL,NOW()),
('q_aj-5-present-simple-3rd_9','Doplň otázku: ... he like pizza?',ARRAY['Are','Does','Is','Do']::TEXT[],1,'Does he like pizza?',4,ARRAY[]::TEXT[],NULL,9,'c_aj-5-present-simple-3rd',NULL,NOW()),
('q_aj-5-present-simple-3rd_10','Odpověz: Does she live in Prague? (ano)',ARRAY['Yes, she is.','Yes, she does.','Yes, she lives.','Yes, she do.']::TEXT[],1,'Yes, she does.',4,ARRAY[]::TEXT[],NULL,10,'c_aj-5-present-simple-3rd',NULL,NOW()),
('q_aj-5-present-simple-3rd_11','Odpověz: Does he play football? (ne)',ARRAY['No, he isn''t.','No, he doesn''t.','No, he don''t.','No, he not.']::TEXT[],1,'No, he doesn''t.',4,ARRAY[]::TEXT[],NULL,11,'c_aj-5-present-simple-3rd',NULL,NOW()),
