('q_aj-5-present-simple-3rd_13','Jak zní otázka: Kde bydlí Eva?',ARRAY['Where Eva lives?','Where does Eva live?','Where is Eva live?','Where do Eva live?']::TEXT[],1,'Where does Eva live?',5,ARRAY[]::TEXT[],NULL,13,'c_aj-5-present-simple-3rd',NULL,NOW()),
('q_aj-5-present-simple-3rd_14','Kolik -s je ve větě: She likes cats and he likes dogs? (u sloves)',ARRAY['one','four','three','two']::TEXT[],3,'Likes a likes.',5,ARRAY[]::TEXT[],NULL,14,'c_aj-5-present-simple-3rd',NULL,NOW()),
('q_aj-5-present-simple-3rd_15','Doplň: Eva ... a red bike. (má)',ARRAY['has','haves','having','have']::TEXT[],0,'U she/he/it je has.',1,ARRAY[]::TEXT[],NULL,15,'c_aj-5-present-simple-3rd',NULL,NOW()),
