('q_aj-5-present-simple-3rd_17','Doplň: Tom ... to the park. (chodí)',ARRAY['go','going','is go','goes']::TEXT[],3,'Go → goes.',1,ARRAY[]::TEXT[],NULL,17,'c_aj-5-present-simple-3rd',NULL,NOW()),
('q_aj-5-present-simple-3rd_18','Doplň: Anna ... her hair. (češe)',ARRAY['brushes','brushs','brush','brushing']::TEXT[],0,'U -sh přidáváme -es.',1,ARRAY[]::TEXT[],NULL,18,'c_aj-5-present-simple-3rd',NULL,NOW()),
